BEGIN;
CREATE TABLE IF NOT EXISTS organization_memberships(organization_id TEXT NOT NULL,user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('member','volunteer','program_lead','safeguarding_lead','finance_manager','communications_manager','administrator')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS governed_programs(id BIGSERIAL PRIMARY KEY,organization_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','submitted','changes_requested','approved','scheduled','completed','cancelled','reconciled')),version INTEGER NOT NULL DEFAULT 1,program JSONB NOT NULL CHECK(jsonb_typeof(program)='object'),idempotency_key TEXT NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,idempotency_key));
CREATE TABLE IF NOT EXISTS organization_events(id BIGSERIAL PRIMARY KEY,organization_id TEXT NOT NULL,program_id BIGINT NOT NULL REFERENCES governed_programs(id),actor_id BIGINT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS organization_outbox(id BIGSERIAL PRIMARY KEY,organization_id TEXT NOT NULL,program_id BIGINT NOT NULL REFERENCES governed_programs(id),provider TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','processing','succeeded','failed','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,payload JSONB NOT NULL DEFAULT '{}',requested_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS donation_reconciliations(id BIGSERIAL PRIMARY KEY,organization_id TEXT NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,ledger_total_cents BIGINT NOT NULL,processor_total_cents BIGINT NOT NULL,difference_cents BIGINT GENERATED ALWAYS AS(processor_total_cents-ledger_total_cents) STORED,status TEXT NOT NULL CHECK(status IN('open','reviewed','resolved')),approved_by BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS organization_program_state_idx ON governed_programs(organization_id,state);CREATE INDEX IF NOT EXISTS organization_outbox_status_idx ON organization_outbox(status,created_at);
COMMIT;
